/**
 * CloudStream 3 Extension Provider: Movy
 * Generated by CloudStream Extension Studio
 * Author: StreamDev Team
 * Version: 1.4.0 (104)
 * Base URL: https://www.movy.sx/
 */
class MovyProvider : MainAPI() {
    override var mainUrl = "https://www.movy.sx/"
    override var name = "Movy"
    override val hasMainPage = true
    override var lang = "en"
    override val hasQuickSearch = true
    override val hasDownloadSupport = true
    override val supportedTypes = setOf(TvType.Movie, TvType.TvSeries)
    override val vpnStatus = VpnStatus.None

    override val mainPage = mainPageOf(
        "/movies/trending" to "Trending Movies",
        "/series/popular" to "Popular TV Series",
        "/movies" to "Movies",
        "/series" to "Series"
    )

    override suspend fun getMainPage(page: Int, request: MainPageRequest): HomePageResponse {
        val requestUrl = if (page <= 1) "$mainUrl${request.data}" else "$mainUrl${request.data}?page=$page"
        val document = app.get(
            requestUrl,
            headers = mapOf(
                "User-Agent" to "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Referer" to mainUrl
            )
        ).document

        // Parsing section: Trending Movies
        val items = document.select(".movies-grid .movie-card").mapNotNull { card ->
            val title = card.selectFirst(".movie-title")?.text()?.trim() ?: return@mapNotNull null
            val href = fixUrl(card.selectFirst("a.play-btn")?.attr("href") ?: return@mapNotNull null)
            val poster = fixUrlNull(card.selectFirst(".poster-img")?.attr("src"))
            val quality = card.selectFirst(".badge-quality")?.text()?.trim()

            newMovieSearchResponse(title, href, TvType.Movie) {
                this.posterUrl = poster
                if (!quality.isNullOrEmpty()) {
                    addQuality(quality)
                }
            }
        }

        // Parsing section: Popular TV Series
        val items = document.select(".series-grid .series-card").mapNotNull { card ->
            val title = card.selectFirst(".series-title")?.text()?.trim() ?: return@mapNotNull null
            val href = fixUrl(card.selectFirst("a.series-link")?.attr("href") ?: return@mapNotNull null)
            val poster = fixUrlNull(card.selectFirst(".poster-img")?.attr("src"))
            val quality = card.selectFirst(".badge-quality")?.text()?.trim()

            newMovieSearchResponse(title, href, TvType.Movie) {
                this.posterUrl = poster
                if (!quality.isNullOrEmpty()) {
                    addQuality(quality)
                }
            }
        }

        // Parsing section: Movies
        val items = document.select(".movies-grid .movie-card").mapNotNull { card ->
            val title = card.selectFirst(".movie-title")?.text()?.trim() ?: return@mapNotNull null
            val href = fixUrl(card.selectFirst("a.play-btn")?.attr("href") ?: return@mapNotNull null)
            val poster = fixUrlNull(card.selectFirst(".poster-img")?.attr("src"))
            val quality = card.selectFirst(".badge-quality")?.text()?.trim()

            newMovieSearchResponse(title, href, TvType.Movie) {
                this.posterUrl = poster
                if (!quality.isNullOrEmpty()) {
                    addQuality(quality)
                }
            }
        }

        // Parsing section: Series
        val items = document.select(".movies-grid .movie-card").mapNotNull { card ->
            val title = card.selectFirst(".movie-title")?.text()?.trim() ?: return@mapNotNull null
            val href = fixUrl(card.selectFirst("a.play-btn")?.attr("href") ?: return@mapNotNull null)
            val poster = fixUrlNull(card.selectFirst(".poster-img")?.attr("src"))
            val quality = card.selectFirst(".badge-quality")?.text()?.trim()

            newMovieSearchResponse(title, href, TvType.Movie) {
                this.posterUrl = poster
                if (!quality.isNullOrEmpty()) {
                    addQuality(quality)
                }
            }
        }

        return newHomePageResponse(request.name, items)
    }

    override suspend fun search(query: String): List<SearchResponse> {
        val searchPath = "/search?keyword={query}".replace("{query}", query)
        val searchUrl = if (searchPath.startsWith("http")) searchPath else "$mainUrl$searchPath"
        
        val document = app.get("$searchUrl").document

        return document.select(".search-results .result-card").mapNotNull { item ->
            val title = item.selectFirst("h4.result-title")?.text()?.trim() ?: return@mapNotNull null
            val href = fixUrl(item.selectFirst("a.result-anchor")?.attr("href") ?: return@mapNotNull null)
            val poster = fixUrlNull(item.selectFirst("img.result-poster")?.attr("src"))
            val quality = item.selectFirst(".quality-pill")?.text()?.trim()

            newMovieSearchResponse(title, href, TvType.Movie) {
                this.posterUrl = poster
                if (!quality.isNullOrEmpty()) {
                    addQuality(quality)
                }
            }
        }
    }

    override suspend fun load(url: String): LoadResponse {
        val document = app.get(url).document
        val title = document.selectFirst(".detail-header h1.entry-title")?.text()?.trim() ?: "Unknown Title"
        val poster = fixUrlNull(document.selectFirst(".detail-poster img")?.attr("src"))
        val plot = document.selectFirst(".detail-body .plot-summary")?.text()?.trim()
        val year = document.selectFirst(".meta-info .release-year")?.text()?.filter { it.isDigit() }?.toIntOrNull()
        val rating = document.selectFirst(".meta-info .imdb-rating")?.text()?.toRatingInt()
        val tags = document.select(".genres-list .genre-item").map { it.text().trim() }

        // Parse episodes list
        val episodes = document.select(".season-container .episode-row").mapNotNull { epItem ->
            val epName = epItem.selectFirst(".ep-title")?.text()?.trim() ?: "Episode"
            val epHref = fixUrl(epItem.selectFirst("a.ep-link")?.attr("href") ?: return@mapNotNull null)
            
            val epNumRegex = Regex("""Episode\s*(\d+)|E(\d+)""")
            val epNum = epNumRegex.find(epName)?.groupValues?.getOrNull(1)?.toIntOrNull()

            newEpisode(epHref) {
                this.name = epName
                this.episode = epNum
            }
        }

        return if (episodes.isNotEmpty()) {
            newTvSeriesLoadResponse(title, url, TvType.TvSeries, episodes) {
                this.posterUrl = poster
                this.plot = plot
                this.year = year
                this.rating = rating
                this.tags = tags
            }
        } else {
            newMovieLoadResponse(title, url, TvType.Movie, url) {
                this.posterUrl = poster
                this.plot = plot
                this.year = year
                this.rating = rating
                this.tags = tags
            }
        }
    }

    override suspend fun loadLinks(
        data: String,
        isCasting: Boolean,
        subtitleCallback: (SubtitleFile) -> Unit,
        callback: (ExtractorLink) -> Unit
    ): Boolean {
        val document = app.get(data).document

        // Extractor: VidStream Prime (HLS / m3u8)
        val m3u8Regex = Regex("""(?:source|file):\s*["']([^"']+\.m3u8[^"']*)""")
        val htmlContent = document.html()
        m3u8Regex.findAll(htmlContent).forEach { match ->
            val streamUrl = match.groupValues.getOrNull(1) ?: return@forEach
            callback.invoke(
                ExtractorLink(
                    source = "VidStream Prime",
                    name = "VidStream Prime (Auto HLS)",
                    url = fixUrl(streamUrl),
                    referer = "https://cinestream-media.example.com/",
                    quality = Qualities.P1080.value,
                    isM3u8 = true
                )
            )
        }

        // Extractor: StreamTape Embed Resolver (Embed Resolver)
        document.select("iframe.player-frame").forEach { iframe ->
            val iframeSrc = fixUrl(iframe.attr("src"))
            loadExtractor(iframeSrc, data, subtitleCallback, callback)
        }

        return true
    }
}
